import React, { useState, useEffect } from 'react';
import io from 'socket.io-client';
import './Dashboard.css';

const socket = io('http://localhost:3001');

const Dashboard = () => {
    const [results, setResults] = useState({
        participants: [],
        teams: []
    });

    useEffect(() => {
        socket.on('updateResults', (data) => {
            setResults(data);
        });

        // Request initial data
        socket.emit('getResults');

        return () => {
            socket.off('updateResults');
        };
    }, []);

    const getScoreColor = (score) => {
        if (score >= 50) return 'green';
        if (score >= 45) return 'orange';
        return 'red';
    };

    const bestParticipant = results.participants.length > 0 ? results.participants[0] : null;

    return (
        <div className="dashboard-container">
            <h1>Dashboard des Résultats</h1>

            {bestParticipant && (
                <div className="best-participant-card">
                    <h2>🌟 Meilleur Participant 🌟</h2>
                    <h3>{bestParticipant.name}</h3>
                    <p>Score: {bestParticipant.score.toFixed(2)} / 68</p>
                    <p>Niveau: Très bon niveau</p>
                </div>
            )}

            <div className="results-section">
                <h2>Classement par Participant</h2>
                <table className="results-table">
                    <thead>
                        <tr>
                            <th>Rang</th>
                            <th>Nom</th>
                            <th>Équipe</th>
                            <th>Score</th>
                            <th>Statut</th>
                        </tr>
                    </thead>
                    <tbody>
                        {results.participants.map((p, index) => (
                            <tr key={p.name} style={{ color: getScoreColor(p.score) }}>
                                <td>{index + 1}</td>
                                <td>{p.name}</td>
                                <td>{p.team}</td>
                                <td>{p.score.toFixed(2)}</td>
                                <td>{p.score >= 50 ? 'VALIDÉ' : 'NON VALIDÉ'}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            <div className="results-section">
                <h2>Classement par Équipe</h2>
                <table className="results-table">
                    <thead>
                        <tr>
                            <th>Rang</th>
                            <th>Équipe</th>
                            <th>Score Moyen</th>
                        </tr>
                    </thead>
                    <tbody>
                        {results.teams.map((t, index) => (
                            <tr key={t.name}>
                                <td>{index + 1}</td>
                                <td>{t.name}</td>
                                <td>{t.averageScore.toFixed(2)}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default Dashboard;
